from functools import lru_cache

class Solution:
    def minStickers(self, stickers, target):
        target_set = set(target)
        usable = []
        seen = set()

        for sticker in stickers:
            cnt = [0] * 26
            useful = False
            for ch in sticker:
                if ch in target_set:
                    cnt[ord(ch) - 97] += 1
                    useful = True
            if useful:
                key = tuple(cnt)
                if key not in seen:
                    seen.add(key)
                    usable.append(cnt)

        @lru_cache(maxsize=None)
        def dfs(rem):
            if not rem:
                return 0

            first = ord(rem[0]) - 97
            best = 10**9

            for cnt in usable:
                if cnt[first] == 0:
                    continue

                have = cnt[:]
                nxt = []
                for ch in rem:
                    idx = ord(ch) - 97
                    if have[idx]:
                        have[idx] -= 1
                    else:
                        nxt.append(ch)

                nr = ''.join(nxt)
                if nr != rem:
                    sub = dfs(nr)
                    if sub >= 0:
                        best = min(best, 1 + sub)

            return -1 if best == 10**9 else best

        return dfs(''.join(sorted(target)))

