#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char **items;
    int count;
    int pos;
} JsonParser;

static void skip_ws(JsonParser *p) {
    while (p->pos < 1000000) {
        char c = p->items[0][p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ',') p->pos++;
        else break;
    }
}

static char *parse_string(JsonParser *p) {
    char *s = p->items[0];
    while (s[p->pos] == ' ' || s[p->pos] == '\t' || s[p->pos] == ',') p->pos++;
    if (s[p->pos] != '"') return NULL;
    p->pos++;
    int start = p->pos;
    while (s[p->pos] && s[p->pos] != '"') p->pos++;
    int len = p->pos - start;
    char *out = (char *)malloc((size_t)len + 1);
    memcpy(out, s + start, (size_t)len);
    out[len] = '\0';
    if (s[p->pos] == '"') p->pos++;
    return out;
}

static char **parse_string_array(JsonParser *p, int *size) {
    char *s = p->items[0];
    while (s[p->pos] == ' ' || s[p->pos] == '\t' || s[p->pos] == ',') p->pos++;
    if (s[p->pos] != '[') return NULL;
    p->pos++;

    int cap = 16, count = 0;
    char **arr = (char **)malloc((size_t)cap * sizeof(char *));
    while (1) {
        while (s[p->pos] == ' ' || s[p->pos] == '\t' || s[p->pos] == ',') p->pos++;
        if (s[p->pos] == ']') {
            p->pos++;
            break;
        }
        char *word = parse_string(p);
        if (!word) break;
        if (count == cap) {
            cap *= 2;
            arr = (char **)realloc(arr, (size_t)cap * sizeof(char *));
        }
        arr[count++] = word;
        while (s[p->pos] == ' ' || s[p->pos] == '\t') p->pos++;
    }

    *size = count;
    return arr;
}

static unsigned long hash_str(const char *s) {
    unsigned long h = 1469598103934665603UL;
    while (*s) {
        h ^= (unsigned char)*s++;
        h *= 1099511628211UL;
    }
    return h;
}

typedef struct {
    char *key;
    int value;
} MemoEntry;

#define MEMO_CAP (1u << 20)

static MemoEntry *memo_table;

static int memo_get(const char *key, int *out) {
    unsigned long h = hash_str(key);
    size_t idx = h & (MEMO_CAP - 1);
    for (size_t probe = 0; probe < MEMO_CAP; probe++) {
        MemoEntry *e = &memo_table[idx];
        if (e->key == NULL) return 0;
        if (strcmp(e->key, key) == 0) {
            *out = e->value;
            return 1;
        }
        idx = (idx + 1) & (MEMO_CAP - 1);
    }
    return 0;
}

static void memo_put(const char *key, int value) {
    unsigned long h = hash_str(key);
    size_t idx = h & (MEMO_CAP - 1);
    for (size_t probe = 0; probe < MEMO_CAP; probe++) {
        MemoEntry *e = &memo_table[idx];
        if (e->key == NULL || strcmp(e->key, key) == 0) {
            if (e->key == NULL) {
                e->key = strdup(key);
            }
            e->value = value;
            return;
        }
        idx = (idx + 1) & (MEMO_CAP - 1);
    }
}

static int *sticker_counts;
static int sticker_count;
static int target_len;

static int dfs(const char *rem) {
    if (*rem == '\0') return 0;

    int cached;
    if (memo_get(rem, &cached)) return cached;

    int first = rem[0] - 'a';
    int best = 1000000;

    for (int s = 0; s < sticker_count; s++) {
        int *cnt = sticker_counts + s * 26;
        if (cnt[first] == 0) continue;

        int have[26];
        memcpy(have, cnt, sizeof(have));

        char next[27];
        int m = 0;
        for (int i = 0; rem[i] != '\0'; i++) {
            int idx = rem[i] - 'a';
            if (have[idx] > 0) {
                have[idx]--;
            } else {
                next[m++] = rem[i];
            }
        }
        next[m] = '\0';

        if (strcmp(next, rem) == 0) continue;
        int sub = dfs(next);
        if (sub >= 0 && sub + 1 < best) best = sub + 1;
    }

    int ans = (best == 1000000) ? -1 : best;
    memo_put(rem, ans);
    return ans;
}

static int cmp_char(const void *a, const void *b) {
    return (*(const char *)a) - (*(const char *)b);
}

int minStickers(char **stickers, int stickersSize, char *target) {
    int needed[26] = {0};
    for (int i = 0; target[i] != '\0'; i++) needed[target[i] - 'a']++;

    sticker_count = 0;
    sticker_counts = (int *)calloc((size_t)stickersSize * 26, sizeof(int));

    int *seen_keys = NULL;
    (void)seen_keys;

    for (int i = 0; i < stickersSize; i++) {
        int *cnt = sticker_counts + sticker_count * 26;
        int useful = 0;

        for (int j = 0; stickers[i][j] != '\0'; j++) {
            int idx = stickers[i][j] - 'a';
            if (needed[idx] > 0) {
                cnt[idx]++;
                useful = 1;
            }
        }

        if (useful) sticker_count++;
        else memset(cnt, 0, 26 * sizeof(int));
    }

    /* Remove duplicate relevant sticker count vectors. */
    for (int i = 0; i < sticker_count; i++) {
        for (int j = i + 1; j < sticker_count; ) {
            if (memcmp(sticker_counts + i * 26, sticker_counts + j * 26,
                       26 * sizeof(int)) == 0) {
                for (int k = j; k + 1 < sticker_count; k++) {
                    memcpy(sticker_counts + k * 26,
                           sticker_counts + (k + 1) * 26,
                           26 * sizeof(int));
                }
                sticker_count--;
            } else {
                j++;
            }
        }
    }

    char rem[27];
    strcpy(rem, target);
    qsort(rem, strlen(rem), 1, cmp_char);

    memo_table = (MemoEntry *)calloc(MEMO_CAP, sizeof(MemoEntry));
    int ans = dfs(rem);

    for (size_t i = 0; i < MEMO_CAP; i++) {
        free(memo_table[i].key);
    }
    free(memo_table);
    free(sticker_counts);

    return ans;
}

