                for (int x : cnt) {
                    key += to_string(x);
                    key.push_back(',');
                }
                if (seen.insert(key).second) usable.push_back(cnt);
            }
        }

        sort(target.begin(), target.end());
        unordered_map<string, int> memo;
        memo[""] = 0;
        return dfs(target, usable, memo);
    }

private:
    int dfs(const string& rem,
            const vector<array<int, 26>>& usable,
            unordered_map<string, int>& memo) {
        auto it = memo.find(rem);
        if (it != memo.end()) return it->second;

        int first = rem[0] - 'a';
        int best = INT_MAX / 4;

        for (const auto& cnt : usable) {
            if (cnt[first] == 0) continue;

            auto have = cnt;
            string next;

            for (char ch : rem) {
                int idx = ch - 'a';
                if (have[idx] > 0) {
                    have[idx]--;
                } else {
                    next.push_back(ch);
                }
            }

            if (next != rem) {
                int sub = dfs(next, usable, memo);
                if (sub >= 0) best = min(best, 1 + sub);
            }
        }

        int ans = (best >= INT_MAX / 8) ? -1 : best;
        memo[rem] = ans;
        return ans;
    }
