class Solution {
    public int minStickers(String[] stickers, String target) {
        boolean[] needed = new boolean[26];
        for (int i = 0; i < target.length(); i++) {
            needed[target.charAt(i) - 'a'] = true;
        }

        java.util.List<int[]> usable = new java.util.ArrayList<>();
        java.util.Set<String> seen = new java.util.HashSet<>();

        for (String sticker : stickers) {
            int[] cnt = new int[26];
            boolean useful = false;
            for (int i = 0; i < sticker.length(); i++) {
                char ch = sticker.charAt(i);
                if (needed[ch - 'a']) {
                    cnt[ch - 'a']++;
                    useful = true;
                }
            }
            if (useful) {
                String key = java.util.Arrays.toString(cnt);
                if (seen.add(key)) {
                    usable.add(cnt);
                }
            }
        }

        java.util.Map<String, Integer> memo = new java.util.HashMap<>();
        memo.put("", 0);
        String sortedTarget = sortString(target);
        int ans = dfs(sortedTarget, usable, memo);
        return ans;
    }

    private int dfs(String rem, java.util.List<int[]> usable,
                    java.util.Map<String, Integer> memo) {
        if (memo.containsKey(rem)) return memo.get(rem);

        int first = rem.charAt(0) - 'a';
        int best = Integer.MAX_VALUE / 4;

        for (int[] cnt : usable) {
            if (cnt[first] == 0) continue;

            int[] have = cnt.clone();
            StringBuilder next = new StringBuilder();

            for (int i = 0; i < rem.length(); i++) {
                int idx = rem.charAt(i) - 'a';
                if (have[idx] > 0) {
                    have[idx]--;
                } else {
                    next.append(rem.charAt(i));
                }
            }

            String nr = next.toString();
            if (!nr.equals(rem)) {
                int sub = dfs(nr, usable, memo);
                if (sub >= 0) best = Math.min(best, 1 + sub);
            }
        }

        int ans = (best >= Integer.MAX_VALUE / 8) ? -1 : best;
        memo.put(rem, ans);
        return ans;
    }

    private String sortString(String s) {
        char[] a = s.toCharArray();
        java.util.Arrays.sort(a);
        return new String(a);
    }
}

