        }
    }

    const memo = new Map();

    function dfs(rem) {
        if (rem.length === 0) return 0;
        if (memo.has(rem)) return memo.get(rem);

        const first = rem.charCodeAt(0) - 97;
        let best = Infinity;

        for (const cnt of usable) {
            if (cnt[first] === 0) continue;

